import {
  Group,
  Shape,
  ExtrudeGeometry,
  PlaneGeometry,
  Color,
  DirectionalLight,
  DoubleSide,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  uniform,
  vec2,
  vec3,
  mix,
  smoothstep,
  step,
  abs,
  float,
  uv,
  positionLocal,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'gradient-cta';

  // ---- bridging config ----
  const visualSpec = config.visualSpec ?? config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#ff4450' },
      { at: 0.55, hex: '#ff2a38' },
      { at: 1, hex: '#c1121f' },
    ],
  };
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const ctaItem = items.find((i) => i.role === 'cta-label') ?? items[0] ?? { text: 'BEGIN COMMISSION' };
  const captionItem = items.find((i) => i.role === 'caption') ?? items[1] ?? { text: 'NO DEPOSIT REQUIRED' };

  const hexVec3 = (hex) => {
    const c = new THREE.Color(hex);
    return vec3(c.r, c.g, c.b);
  };

  // ---- geometry: rounded-rect extruded button ----
  const width = 2.6;
  const height = 0.68;
  const radius = 0.08;
  const depth = 0.03;

  const x = -width / 2;
  const y = -height / 2;
  const shape = new Shape();
  shape.moveTo(x, y + radius);
  shape.lineTo(x, y + height - radius);
  shape.quadraticCurveTo(x, y + height, x + radius, y + height);
  shape.lineTo(x + width - radius, y + height);
  shape.quadraticCurveTo(x + width, y + height, x + width, y + height - radius);
  shape.lineTo(x + width, y + radius);
  shape.quadraticCurveTo(x + width, y, x + width - radius, y);
  shape.lineTo(x + radius, y);
  shape.quadraticCurveTo(x, y, x, y + radius);

  const geometry = new ExtrudeGeometry(shape, {
    depth,
    bevelEnabled: true,
    bevelThickness: 0.015,
    bevelSize: 0.015,
    bevelSegments: 3,
    curveSegments: 10,
  });
  geometry.center();

  // ---- TSL engineered gradient with hard seam ----
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#ff4450' },
    { at: 0.55, hex: '#ff2a38' },
    { at: 1, hex: '#c1121f' },
  ];
  const c0 = hexVec3(stops[0].hex);
  const c1 = hexVec3(stops[1].hex);
  const c2 = hexVec3(stops[2].hex);
  const seamAt = stops[1].at;

  const t = positionLocal.y.div(height).add(0.5); // 0..1 across face height

  const gradLower = mix(c0, c1, smoothstep(float(0.0), float(seamAt), t));
  const gradUpper = mix(c1, c2, smoothstep(float(seamAt), float(1.0), t));
  const gradient = mix(gradLower, gradUpper, step(float(seamAt), t));

  const seamWidth = 0.01 / height;
  const seamMask = float(1.0).sub(smoothstep(float(0.0), float(seamWidth), abs(t.sub(seamAt))));
  const gradedColor = gradient.mul(float(1.0).sub(seamMask.mul(0.35)));

  // ---- perimeter emissive edge mask ----
  const halfW = width / 2;
  const halfH = height / 2;
  const edgeThickness = 0.02;
  const edgeX = smoothstep(float(halfW - edgeThickness), float(halfW), abs(positionLocal.x));
  const edgeY = smoothstep(float(halfH - edgeThickness), float(halfH), abs(positionLocal.y));
  const edgeMask = edgeX.max(edgeY);

  const accentColor = hexVec3(colors.accent ?? '#ff2a38');
  const emissiveIntensity = uniform(1.6);
  const emissiveNode = accentColor.mul(edgeMask).mul(emissiveIntensity);
  const baseColorNode = mix(gradedColor, accentColor, edgeMask.mul(0.5));

  const material = new MeshPhysicalNodeMaterial({
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22,
    clearcoatRoughness: 0.3,
  });
  material.colorNode = baseColorNode;
  material.emissiveNode = emissiveNode;
  material.side = DoubleSide;

  const buttonMesh = new THREE.Mesh(geometry, material);
  root.add(buttonMesh);

  // ---- accent edge light (DL12) ----
  const rimLight = new DirectionalLight(new Color(colors.accent ?? '#ff2a38'), 1.0);
  rimLight.position.set(-1.4, 0.9, 1.6);
  root.add(rimLight);

  // ---- contact shadow ----
  const shadowGeo = new PlaneGeometry(width * 1.3, height * 2.2);
  const shadowOpacity = uniform(0.45);
  const shadowUv = uv();
  const shadowDist = shadowUv.sub(vec2(0.5, 0.5)).length();
  const shadowFalloff = float(1.0).sub(smoothstep(float(0.0), float(0.5), shadowDist));
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = shadowFalloff.mul(shadowOpacity);
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -halfH - 0.08, -0.02);
  root.add(shadowMesh);

  // ---- label + caption text ----
  const ctaFontSize = ctaItem?.typography?.fontSize ?? 20;
  const labelText = ctx.fontAtlas.createText(ctaItem?.text ?? 'BEGIN COMMISSION', {
    fontSize: ctaFontSize,
    color: colors.paper ?? '#e8ecf2',
    align: 'center',
    letterSpacingPx: (ctaItem?.typography?.letterSpacing ?? 0.08) * ctaFontSize,
  });
  labelText.position.set(0, 0, depth / 2 + 0.02);
  root.add(labelText);

  const captionFontSize = captionItem?.typography?.fontSize ?? 9;
  const captionText = ctx.fontAtlas.createText(captionItem?.text ?? 'NO DEPOSIT REQUIRED', {
    fontSize: captionFontSize,
    color: colors.paper ?? '#e8ecf2',
    align: 'center',
    letterSpacingPx: (captionItem?.typography?.letterSpacing ?? 0.12) * captionFontSize,
  });
  captionText.position.set(0, -halfH - 0.25, 0.01);
  root.add(captionText);

  // ---- motion ----
  const timelines = [];

  const mountTl = gsap.timeline();
  mountTl.fromTo(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  timelines.push(mountTl);

  // idle breathing (weighted, single slow transform)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 0.9 });
  idleTl.to(buttonMesh.scale, { x: 1.01, y: 1.01, z: 1.01, duration: 2.6, ease: 'sine.inOut' });
  timelines.push(idleTl);

  root.userData.handlers = {
    onPointerOver: () => {
      const tl = gsap.timeline();
      tl.to(buttonMesh.position, { z: 0.06, duration: 0.18, ease: 'power2.out' }, 0);
      tl.to(emissiveIntensity, { value: 2.2, duration: 0.18, ease: 'power2.out' }, 0);
      timelines.push(tl);
    },
    onPointerOut: () => {
      const tl = gsap.timeline();
      tl.to(buttonMesh.position, { z: 0, duration: 0.18, ease: 'power2.out' }, 0);
      tl.to(emissiveIntensity, { value: 1.6, duration: 0.18, ease: 'power2.out' }, 0);
      timelines.push(tl);
    },
    onPointerDown: () => {
      const tl = gsap.timeline();
      tl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' }, 0);
      tl.to(shadowOpacity, { value: 0.6, duration: 0.12, ease: 'power2.out' }, 0);
      tl.to(shadowMesh.scale, { x: 0.85, y: 0.85, duration: 0.12, ease: 'power2.out' }, 0);
      timelines.push(tl);
    },
    onPointerUp: () => {
      const tl = gsap.timeline();
      tl.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power3.out' }, 0);
      tl.to(shadowOpacity, { value: 0.45, duration: 0.2, ease: 'power2.out' }, 0);
      tl.to(shadowMesh.scale, { x: 1, y: 1, duration: 0.2, ease: 'power2.out' }, 0);
      timelines.push(tl);
    },
    onClick: () => {
      ctx.emit('cta:click', {
        id: config.id ?? 'gradient-cta',
        label: ctaItem?.text ?? 'BEGIN COMMISSION',
      });
    },
  };

  // ---- cinematic primitives (contract-required loop, empty by spec) ----
  const primitiveCleanups = [];
  for (const prim of config.cinematicPrimitives ?? []) {
    const applied = ctx.primitives[prim.name]?.(root, prim.params);
    if (applied?.timeline) timelines.push(applied.timeline);
    if (applied?.cleanup) primitiveCleanups.push(applied.cleanup);
  }

  // ---- cleanup ----
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    primitiveCleanups.forEach((fn) => fn());

    geometry.dispose();
    material.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    if (typeof labelText.userData?.cleanup === 'function') labelText.userData.cleanup();
    if (typeof captionText.userData?.cleanup === 'function') captionText.userData.cleanup();
    labelText.geometry?.dispose?.();
    labelText.material?.dispose?.();
    captionText.geometry?.dispose?.();
    captionText.material?.dispose?.();

    root.remove(rimLight);
    root.clear();
  };

  return root;
}
